<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { Database, Eye, EyeOff, FileUp, Pencil, Plus, Save, Search, Trash2, X } from 'lucide-vue-next'
import { useRoute } from 'vue-router'
import AdminModuleHeader from '../components/AdminModuleHeader.vue'
import { api } from '../api'

type City = { id: number; name: string }
type AttractionRow = { id: number; city_id: number; city_name: string; name: string; description: string; tags: string[]; opening_hours: string; ticket_price: number; duration_minutes: number; area: string; latitude: number | null; longitude: number | null; image_url: string; source: string; is_active: boolean }
type AttractionForm = Omit<AttractionRow, 'id' | 'city_name' | 'tags' | 'latitude' | 'longitude'> & { tags: string; latitude: string; longitude: string }
const emptyForm = (cityId = 0): AttractionForm => ({ city_id: cityId, name: '', description: '', tags: '', opening_hours: '全天开放', ticket_price: 0, duration_minutes: 120, area: '', latitude: '', longitude: '', image_url: '', source: '管理员维护', is_active: true })
const route = useRoute(); const cities = ref<City[]>([]); const attractions = ref<AttractionRow[]>([]); const cityFilter = ref(Number(route.query.city) || 0); const search = ref(''); const error = ref(''); const notice = ref(''); const editingId = ref<number | null>(null); const form = ref<AttractionForm>(emptyForm(cityFilter.value)); const showImport = ref(false); const saving = ref(false)
const importText = ref('[\n  {\n    "city_id": 1,\n    "name": "示例景点",\n    "description": "景点介绍",\n    "tags": ["文化"],\n    "opening_hours": "09:00-17:00",\n    "ticket_price": 0,\n    "duration_minutes": 120,\n    "area": "城区"\n  }\n]')
const filteredAttractions = computed(() => { const keyword = search.value.trim().toLowerCase(); return attractions.value.filter((item) => (!cityFilter.value || item.city_id === cityFilter.value) && (!keyword || `${item.name} ${item.description} ${item.tags.join(' ')}`.toLowerCase().includes(keyword))) })
function toPayload() { return { ...form.value, tags: form.value.tags.split(/[,，]/).map((item) => item.trim()).filter(Boolean), latitude: form.value.latitude === '' ? null : Number(form.value.latitude), longitude: form.value.longitude === '' ? null : Number(form.value.longitude) } }
function edit(item?: AttractionRow) { editingId.value = item?.id ?? null; form.value = item ? { ...item, tags: item.tags.join(', '), latitude: item.latitude === null ? '' : String(item.latitude), longitude: item.longitude === null ? '' : String(item.longitude) } : emptyForm(cityFilter.value); notice.value = '' }
async function load() { [cities.value, attractions.value] = await Promise.all([api<City[]>('/admin/cities'), api<AttractionRow[]>('/admin/attractions')]) }
async function save() { saving.value = true; notice.value = ''; try { const message = editingId.value ? '景点资料已保存' : '景点已新增'; const path = editingId.value ? `/admin/attractions/${editingId.value}` : '/admin/attractions'; await api(path, { method: editingId.value ? 'PATCH' : 'POST', body: JSON.stringify(toPayload()) }); await load(); edit(); notice.value = message } catch (exception) { notice.value = exception instanceof Error ? exception.message : '保存失败' } finally { saving.value = false } }
async function toggleActive(item: AttractionRow) { const action = item.is_active ? '停用' : '启用'; if (!window.confirm(`确定${action}景点“${item.name}”吗？`)) return; try { await api(`/admin/attractions/${item.id}`, { method: 'PATCH', body: JSON.stringify({ is_active: !item.is_active }) }); await load(); notice.value = `景点已${action}` } catch (exception) { notice.value = exception instanceof Error ? exception.message : `${action}失败` } }
async function remove(item: AttractionRow) { if (!window.confirm(`确定彻底删除景点“${item.name}”吗？此操作不能撤销，存在任何关联数据时系统会拒绝。`)) return; try { await api(`/admin/attractions/${item.id}`, { method: 'DELETE' }); await load(); notice.value = '景点已彻底删除' } catch (exception) { notice.value = exception instanceof Error ? exception.message : '删除失败' } }
async function importItems() { try { const items = JSON.parse(importText.value); if (!Array.isArray(items)) throw new Error('导入内容必须是 JSON 数组'); await api('/admin/attractions/import', { method: 'POST', body: JSON.stringify({ items }) }); await load(); notice.value = `已导入 ${items.length} 个景点`; showImport.value = false } catch (exception) { notice.value = exception instanceof Error ? exception.message : '导入失败' } }
onMounted(async () => { try { await load() } catch (exception) { error.value = exception instanceof Error ? exception.message : '加载失败' } })
</script>

<template><div class="page-container"><AdminModuleHeader eyebrow="ATTRACTION DATA" title="景点管理" description="维护景点内容、上架状态、开放信息、票价和资料来源。" /><div v-if="error" class="empty-state"><Database :size="28" /><h2>{{ error }}</h2></div><template v-else><div class="admin-toolbar"><div class="admin-toolbar-group"><button :class="['admin-filter-button', { active: cityFilter === 0 }]" @click="cityFilter = 0">全部城市</button><button v-for="city in cities" :key="city.id" :class="['admin-filter-button', { active: cityFilter === city.id }]" @click="cityFilter = city.id">{{ city.name }}</button></div><div class="admin-toolbar-group"><button class="secondary-button" @click="showImport = !showImport"><FileUp :size="16" />批量导入</button><button class="primary-button" @click="edit()"><Plus :size="16" />新增景点</button><input v-model="search" class="admin-search" placeholder="搜索景点、介绍或标签" /></div></div><p v-if="notice" class="admin-notice">{{ notice }}</p><section class="admin-editor"><div class="admin-editor-heading"><h2>{{ editingId ? '编辑景点' : '新增景点' }}</h2><button class="admin-table-action" title="关闭编辑" @click="edit()"><X :size="16" /></button></div><div class="admin-form-grid"><label>所属城市<select v-model.number="form.city_id"><option :value="0" disabled>选择城市</option><option v-for="city in cities" :key="city.id" :value="city.id">{{ city.name }}</option></select></label><label>景点名称<input v-model="form.name" /></label><label>标签（逗号分隔）<input v-model="form.tags" /></label><label>开放时间<input v-model="form.opening_hours" /></label><label>票价<input v-model.number="form.ticket_price" type="number" min="0" /></label><label>建议时长（分钟）<input v-model.number="form.duration_minutes" type="number" min="10" /></label><label>区域<input v-model="form.area" /></label><label>资料来源<input v-model="form.source" /></label><label>纬度<input v-model="form.latitude" type="number" /></label><label>经度<input v-model="form.longitude" type="number" /></label><label class="admin-form-wide">图片地址<input v-model="form.image_url" /></label><label class="admin-form-wide">景点介绍<textarea v-model="form.description" rows="3" /></label><label class="admin-check"><input v-model="form.is_active" type="checkbox" />在前台展示</label></div><button class="primary-button" :disabled="saving" @click="save"><Save :size="16" />{{ saving ? '保存中' : '保存景点' }}</button></section><section v-if="showImport" class="admin-editor"><div class="admin-editor-heading"><h2>批量导入景点</h2><button class="admin-table-action" title="关闭导入" @click="showImport = false"><X :size="16" /></button></div><textarea v-model="importText" class="admin-json-input" rows="13" aria-label="景点 JSON 导入内容" /><button class="primary-button" @click="importItems"><FileUp :size="16" />导入 JSON</button></section><div class="admin-table-wrap"><table class="admin-data-table"><thead><tr><th>景点</th><th>城市</th><th>区域</th><th>开放时间</th><th>票价</th><th>建议时长</th><th>资料来源</th><th>状态</th><th aria-label="操作"></th></tr></thead><tbody><tr v-for="item in filteredAttractions" :key="item.id"><td><strong>{{ item.name }}</strong><small>{{ item.tags.join(' · ') }}</small></td><td>{{ item.city_name }}</td><td>{{ item.area }}</td><td>{{ item.opening_hours }}</td><td>¥{{ item.ticket_price }}</td><td>{{ item.duration_minutes }} 分钟</td><td>{{ item.source }}</td><td><span :class="['admin-status', { muted: !item.is_active }]">{{ item.is_active ? '已上架' : '已停用' }}</span></td><td class="admin-table-actions"><button class="admin-table-action" title="编辑景点" @click="edit(item)"><Pencil :size="16" /></button><button class="admin-table-action" :title="item.is_active ? '停用景点' : '启用景点'" @click="toggleActive(item)"><EyeOff v-if="item.is_active" :size="16" /><Eye v-else :size="16" /></button><button v-if="!item.is_active" class="admin-table-action danger-action" title="彻底删除景点" @click="remove(item)"><Trash2 :size="16" /></button></td></tr></tbody></table><div v-if="!filteredAttractions.length" class="admin-page-empty"><Search :size="20" /><p>没有匹配的景点</p></div></div></template></div></template>
